use vstd::prelude::*;

verus! {
    /// Function to rotate an array to the right by a given amount.
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0, // The input array must be non-empty
        ensures
            new_list.len() == list.len(), // The output array has the same length
            forall(|i: usize| 0 <= i < list.len() ==> new_list[i] == list[(i + (n % list.len())) % list.len()]), // The elements are correctly rotated
    {
        let len = list.len();
        let mut new_list: Vec<u32> = Vec::new();
        new_list.resize(len, 0); // Initialize the new list with the same length

        let s = len - (n % len); // Calculate the starting index for the suffix

        // Fill the new list with the rotated values
        for i in 0..len {
            if i < len - s {
                new_list[i] = list[s + i]; // Fill from the suffix
            } else {
                new_list[i] = list[i - (len - s)]; // Fill from the prefix
            }
        }

        new_list // Return the new rotated list
    }
}
